const copy = {
    preview:"DİZAYN NÜMAYİŞİ",choose:"Dizayn istiqamətini seçin",navServices:"Xidmətlər",navBarbers:"Bərbərlərimiz",navVisit:"Ünvan",book:"Vaxt təyin et",eyebrow:"MƏHƏLLƏNİZİN YENİ NƏSİL BƏRBƏR SALONU",hero:"Saçınız gözəl.<br><em>Əhvalınız daha da.</em>",heroText:"Səliqəli saç kəsimi, xoş söhbət və özünüzə ayırdığınız bir saat. Necəsinizsə, elə gəlin. Daha yaxşı hiss edərək ayrılın.",bookAppointment:"Görüş təyin edin",explore:"Xidmətlərə baxın",openToday:"BU GÜN AÇIQDIR · 09:00—19:00",yourCity:"ŞƏHƏRİNİZ, MƏHƏLLƏNİZ",photoCaption:"XOŞ İNSANLAR. PEŞƏKAR İŞ.",takeSeat:"Əyləşin<br>bir az dincəlin",since:"ÖZÜNÜZ KİMİ OLACAĞINIZ MƏKAN — 2024-DƏN",intro:"Sadəcə saç kəsimi deyil.<br><em>Özünüzə xoş bir saat.</em>",neighbors:"280-DƏN ÇOX MƏMNUN MÜŞTƏRİ",servicesEyebrow:"YAXŞI XİDMƏTLƏR",servicesTitle:"Sizə uyğun<br><em>olanı seçin.</em>",servicesIntro:"Xidmətləri bərbər və qiymət üzrə müqayisə edin, sonra sizə uyğun görüşü seçin.",serviceNames:["İmza saç kəsimi","Saç və saqqal","Saqqal forması","Tam qulluq"],serviceDescriptions:["Sizə yaraşan, səliqəli saç kəsimi.","Təzə kəsim, dəqiq konturlar və isti dəsmal.","Saqqalınıza səliqəli forma verək.","Saç və saqqal kəsimi, yuma və rahatlıq."],consult:"Hər görüşə qısa məsləhətləşmə və ikram daxildir.",bookService:"Xidmət sifariş edin",teamEyebrow:"USTALARIMIZLA TANIŞ OLUN",teamTitle:"Xoş insanlar.<br><em>Etibarlı əllər.</em>",teamIntro:"Söhbətcil, işində dəqiq. Ustalarımızla tanış olun və özünüzə uyğununu seçin.",roles:["Təsisçi · Kəsim və fade","Bərbər · Saç teksturası üzrə","Bərbər · Saqqal dizaynı üzrə"],quote:"“İllərdir etdirdiyim ən yaxşı saç kəsimidir.<br>Qəhvələri də əladır.”",regular:"— TAYLOR R. · 2022-DƏN DAİMİ MÜŞTƏRİ",galleryEyebrow:"SALONUMUZDAN GÖRÜNTÜLƏR",galleryTitle:"Good Cut-da<br><em>gözəl günlər.</em>",comeSee:"Özünüz gəlib görün",visitEyebrow:"GƏLİN, RAHAT ƏYLƏŞİN",visitTitle:"Sizin üçün<br><em>yerimiz var.</em>",visitText:"Boş yer olduqda növbəsiz də qəbul edirik. Görüş təyin etsəniz, sizi gözləyəcəyik.",findTime:"Vaxt seçin",findUs:"ÜNVAN",comeIn:"İŞ SAATLARI",address:"123 Placeholder küçəsi<br>Məhəlləniz, şəhər",hours:"Ç.a.—Cümə · 09:00—19:00<br>Şənbə · 10:00—17:00",map:"GOOD CUT · ŞƏHƏRİNİZ",footerLine:"GÖZƏL KƏSİM. XOŞ İNSANLAR. YAXŞI ƏHVAL.",bookingEyebrow:"BUYURUN, GƏLİN",bookingTitle:"Gəlin,<br><em>özünüzə vaxt ayırın.</em>",bookingIntro:"Nə istədiyinizi yazın. Görüş vaxtını sizinlə dəqiqləşdirəcəyik.",name:"Adınız",namePlaceholder:"Sizə necə müraciət edək?",contact:"E-poçt ünvanı",contactPlaceholder:"name@example.com",service:"Xidmət",selectService:"Xidmət seçin",date:"Uyğun gün",note:"Əlavə qeyd",optional:"İSTƏYƏ BAĞLI",notePlaceholder:"Bərbəriniz üçün qeyd",request:"Görüş üçün müraciət edin",demo:"E-poçt ünvanınız görüşlə bağlı lazım olduqda əlaqə üçün saxlanılır.",successEyebrow:"ƏLA!",successTitle:"Görüşünüz<br><em>təsdiqləndi.</em>",successText:"Görüşünüz dərhal təsdiqləndi. Lazım olduqda salon sizinlə əlaqə saxlayacaq.",back:"Salona qayıt",close:"Formanı bağla",barberBook:"usta ilə görüş təyin edin"
};

const calendarCopy = { barberLabel:"Bərbər seçin", pickBarber:"Bərbər seçin", calendarTitle:"Görüş günü", availabilityNote:"Mövcud vaxtlar", chooseBarberFirst:"Boş vaxtları görmək üçün əvvəlcə bərbər seçin.", chooseDay:"Mövcud saatları görmək üçün günü seçin.", chooseService:"Əvvəlcə xidmət seçin.", loading:"Boş vaxtlar yüklənir…", loadError:"Boş vaxtları yükləmək mümkün olmadı. Yenidən yoxlayın.", available:"boş vaxt", availablePlural:"boş vaxt", chooseTime:"Saat seçin", none:"Bu gün üçün boş saat qalmayıb.", missing:"Zəhmət olmasa bərbər, xidmət, gün və saat seçin.", prev:"Əvvəlki ay", next:"Növbəti ay", weekdays:["B.e","Ç.a","Çər","C.a","Cüm","Şən","Baz"] };

const themeLabels = { light: "İşıqlı rejim", dark: "Tünd rejim", switchLight: "İşıqlı rejimə keç", switchDark: "Tünd rejimə keç" };

const bookingMessages = { unavailable:"Bu vaxt yenicə tutulub. Başqa vaxt seçin.", failed:"Görüşü təsdiqləmək mümkün olmadı. Yenidən cəhd edin.", confirmed:"Görüşünüz dərhal təsdiqləndi. Lazım olduqda salon sizinlə əlaqə saxlayacaq.", sending:"Təsdiqlənir…" };

let galleryPhotos = [];
let catalog = { barbers: [], services: [] };
let availabilityDays = {};
let availabilityKey = "";
let availabilityRequestId = 0;
let loadingAvailability = false;
let availabilityError = "";
let theme = "dark";
try { theme = localStorage.getItem("good-cut-theme") || "dark"; } catch {}
if (theme !== "light" && theme !== "dark") theme = "dark";
let shopTimezone = "Asia/Baku";

function dateTodayInShopTimezone(timeZone) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(new Date()).map((part) => [part.type, part.value]));
  return new Date(Number(parts.year), Number(parts.month) - 1, Number(parts.day));
}

let today = dateTodayInShopTimezone(shopTimezone);
let calendarMonth = new Date(today.getFullYear(), today.getMonth(), 1);
let firstBookableMonth = new Date(today.getFullYear(), today.getMonth(), 1);
let lastBookableMonth = new Date(today.getFullYear(), today.getMonth() + 11, 1);
let selectedDate = "";
let selectedTime = "";

function setCalendarTimezone(timeZone) {
  try {
    const nextToday = dateTodayInShopTimezone(timeZone);
    shopTimezone = timeZone;
    today = nextToday;
    firstBookableMonth = new Date(today.getFullYear(), today.getMonth(), 1);
    lastBookableMonth = new Date(today.getFullYear(), today.getMonth() + 11, 1);
    calendarMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  } catch {}
}

function dateKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function selectedBarberId() {
  return document.querySelector("#booking-barber").value;
}

function drawCalendar() {
  const words = calendarCopy;
  const locale = "az-AZ";
  const barberId = selectedBarberId();
  const serviceId = document.querySelector("#booking-service").value;
  const monthLabel = new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" }).format(calendarMonth);
  document.querySelector("#calendar-month-label").textContent = monthLabel;
  const displayedMonthIndex = calendarMonth.getFullYear() * 12 + calendarMonth.getMonth();
  const firstBookableMonthIndex = firstBookableMonth.getFullYear() * 12 + firstBookableMonth.getMonth();
  const lastBookableMonthIndex = lastBookableMonth.getFullYear() * 12 + lastBookableMonth.getMonth();
  document.querySelector("#calendar-prev").disabled = displayedMonthIndex <= firstBookableMonthIndex;
  document.querySelector("#calendar-next").disabled = displayedMonthIndex >= lastBookableMonthIndex;
  document.querySelector("#calendar-prev").setAttribute("aria-label", words.prev);
  document.querySelector("#calendar-next").setAttribute("aria-label", words.next);
  document.querySelector("#calendar-weekdays").innerHTML = words.weekdays.map((day) => `<span>${day}</span>`).join("");

  const firstWeekday = (calendarMonth.getDay() + 6) % 7;
  const daysInMonth = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 0).getDate();
  const cells = Array.from({ length: firstWeekday }, () => '<span class="calendar-spacer"></span>');
  for (let day = 1; day <= daysInMonth; day++) {
    const date = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), day);
    const key = dateKey(date);
    const slots = availabilityDays[key] || [];
    const disabled = !barberId || !serviceId || loadingAvailability || slots.length === 0;
    const countLabel = words.availablePlural;
    const availability = disabled ? "" : `<small>${slots.length}</small>`;
    const chosen = selectedDate === key ? " chosen" : "";
    const todayClass = key === dateKey(today) ? " today" : "";
    cells.push(`<button type="button" class="calendar-day${chosen}${todayClass}" data-calendar-day="${key}" ${disabled ? "disabled" : ""} aria-label="${day}, ${monthLabel}${slots.length ? `, ${slots.length} ${countLabel}` : ""}"><span>${day}</span>${availability}</button>`);
  }
  document.querySelector("#calendar-days").innerHTML = cells.join("");

  const hint = document.querySelector("#calendar-hint");
  if (!barberId) hint.textContent = words.chooseBarberFirst;
  else if (!serviceId) hint.textContent = words.chooseService;
  else if (loadingAvailability) hint.textContent = words.loading;
  else if (availabilityError) hint.textContent = words.loadError;
  else if (!selectedDate) hint.textContent = words.chooseDay;
  else hint.textContent = "";
  hint.hidden = !hint.textContent;
  renderTimeSlots();
}

function renderCalendar() {
  const barberId = selectedBarberId();
  const serviceId = document.querySelector("#booking-service").value;
  const month = `${calendarMonth.getFullYear()}-${String(calendarMonth.getMonth() + 1).padStart(2, "0")}`;
  const requestKey = `${barberId}|${serviceId}|${month}`;
  if (!barberId || !serviceId) {
    availabilityRequestId++;
    availabilityKey = "";
    availabilityDays = {};
    availabilityError = "";
    loadingAvailability = false;
    drawCalendar();
    return;
  }
  if (requestKey === availabilityKey) {
    drawCalendar();
    return;
  }

  availabilityKey = requestKey;
  availabilityDays = {};
  availabilityError = "";
  loadingAvailability = true;
  const requestId = ++availabilityRequestId;
  drawCalendar();
  fetch(`/api/availability?barberId=${encodeURIComponent(barberId)}&serviceId=${encodeURIComponent(serviceId)}&month=${month}`)
    .then(async (response) => {
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Availability request failed.");
      return data;
    })
    .then((data) => {
      if (requestId !== availabilityRequestId) return;
      availabilityDays = data.days || {};
      loadingAvailability = false;
      drawCalendar();
    })
    .catch(() => {
      if (requestId !== availabilityRequestId) return;
      loadingAvailability = false;
      availabilityError = calendarCopy.loadError;
      drawCalendar();
    });
}

function renderTimeSlots() {
  const panel = document.querySelector("#slots-panel");
  const list = document.querySelector("#time-slots");
  const title = document.querySelector("#slots-title");
  if (!selectedDate || !selectedBarberId() || !document.querySelector("#booking-service").value) {
    panel.hidden = true;
    list.innerHTML = "";
    return;
  }

  const words = calendarCopy;
  const [year, month, day] = selectedDate.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  const locale = "az-AZ";
  title.textContent = `${new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long" }).format(date)} · ${words.chooseTime}`;
  const slots = availabilityDays[selectedDate] || [];
  panel.hidden = false;
  if (!slots.length) {
    list.innerHTML = `<span class="no-slots">${words.none}</span>`;
    return;
  }
  list.innerHTML = slots.map((time) => `<button type="button" class="time-slot${selectedTime === time ? " chosen" : ""}" data-time="${time}">${time}</button>`).join("");
}

function escapeHtml(value = "") {
  return String(value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
}

function updateBookingServices() {
  const serviceSelect = document.querySelector("#booking-service");
  const barberId = selectedBarberId();
  const availableServices = catalog.services.filter((service) => service.barberId === barberId);
  const priorService = availableServices.some((service) => service._id === serviceSelect.value) ? serviceSelect.value : "";
  serviceSelect.innerHTML = `<option value="">${copy.selectService}</option>` + availableServices.map((service) => `<option value="${escapeHtml(service._id)}">${escapeHtml(service.name)} · ₼${escapeHtml(service.price)} · ${escapeHtml(service.durationMinutes)} dəq.</option>`).join("");
  serviceSelect.value = priorService;
}

function renderServices() {
  const barberSelect = document.querySelector("#booking-barber");
  const priorBarber = barberSelect.value;
  barberSelect.innerHTML = `<option value="">${calendarCopy.pickBarber}</option>` + catalog.barbers.map((barber) => `<option value="${escapeHtml(barber._id)}">${escapeHtml(barber.name)}</option>`).join("");
  barberSelect.value = priorBarber;
  updateBookingServices();
  document.querySelector("#service-list").innerHTML = catalog.barbers.map((barber) => {
    const servicesForBarber = catalog.services.filter((service) => service.barberId === barber._id);
    if (!servicesForBarber.length) return "";
    return `<section class="service-group"><h3>${escapeHtml(barber.name)}</h3>${servicesForBarber.map((service, index) => `
      <button class="service-row" type="button" data-service-index="${escapeHtml(service._id)}" data-booker-id="${escapeHtml(barber._id)}"><span class="service-num">0${index + 1}</span><span class="service-info"><strong>${escapeHtml(service.name)}</strong><small>${escapeHtml(service.description || "")}</small></span><span class="service-time">${escapeHtml(service.durationMinutes)} dəq.</span><span class="service-price">₼${escapeHtml(service.price)}</span><span class="service-arrow">↗</span></button>`).join("")}</section>`;
  }).join("") || '<p class="empty-services">Xidmət məlumatları hazırda yenilənir.</p>';
}

function renderBarbers() {
  document.querySelector("#barber-grid").innerHTML = catalog.barbers.map((barber, i) => {
    const name = escapeHtml(barber.name);
    const role = escapeHtml(barber.role);
    const photoUrl = escapeHtml(barber.photoUrl || "");
    return `<article class="barber-card"><div class="barber-image" style="background-image:url(&quot;${photoUrl}&quot;)"><span>0${i + 1}</span></div><div class="barber-caption"><div><h3>${name}</h3><p>${role}</p></div><button type="button" data-open-booking data-booker-id="${escapeHtml(barber._id)}" aria-label="${copy.barberBook} ${name}">↗</button></div></article>`;
  }).join("");
}

function renderAbout() {
  const about = catalog.siteContent?.about;
  if (!about) return;
  document.querySelector("#about-kicker").textContent = about.kicker || "";
  document.querySelector("#about-title").textContent = about.title || "";
  document.querySelector("#about-paragraph-1").textContent = about.paragraph1 || "";
  document.querySelector("#about-paragraph-2").textContent = about.paragraph2 || "";
  document.querySelector("#about-note").textContent = about.note || "";
}

async function loadCatalog() {
  try {
    const response = await fetch("/api/catalog");
    if (!response.ok) throw new Error("Xidmət siyahısını yükləmək mümkün olmadı.");
    catalog = await response.json();
    setCalendarTimezone(catalog.timezone || shopTimezone);
    renderServices();
    renderBarbers();
    renderAbout();
    const heroUrl = catalog.siteContent?.photos?.hero;
    if (heroUrl) document.querySelector(".hero-img").style.backgroundImage = `linear-gradient(180deg,rgba(10,12,10,.02),rgba(10,12,10,.38)),url("${heroUrl}")`;
    renderGallery();
    renderCalendar();
  } catch (error) {
    console.error(error);
  }
}

function renderGallery() {
  galleryPhotos = catalog.siteContent?.photos?.gallery || [];
  document.querySelector("#gallery-grid").innerHTML = galleryPhotos.map((photo, i) => `
    <div class="gallery-photo gallery-photo-${i + 1}" style="background-image:url(&quot;${escapeHtml(photo)}&quot;)"><span>GOOD CUT / 0${i + 1}</span></div>`).join("");
}

function syncThemeToggle() {
  const isLight = document.querySelector(".site").classList.contains("look-studio");
  const labels = themeLabels;
  const button = document.querySelector("#theme-toggle");
  button.setAttribute("aria-pressed", String(isLight));
  button.setAttribute("aria-label", isLight ? labels.switchDark : labels.switchLight);
  document.querySelector(".theme-icon").textContent = isLight ? "☾" : "☼";
  document.querySelector("#theme-label").textContent = isLight ? labels.dark : labels.light;
  document.querySelector('meta[name="theme-color"]').content = isLight ? "#f3f0e8" : "#191a17";
}

function setTheme(nextTheme) {
  const site = document.querySelector(".site");
  theme = nextTheme;
  site.classList.toggle("look-studio", theme === "light");
  site.classList.toggle("look-atelier", theme === "dark");
  try { localStorage.setItem("good-cut-theme", theme); } catch {}
  syncThemeToggle();
}

function applyContent() {
  document.documentElement.lang = "az";
  const t = copy;
  document.querySelectorAll("[data-i18n]").forEach((element) => { element.innerHTML = t[element.dataset.i18n]; });
  document.querySelectorAll("[data-placeholder]").forEach((element) => { element.placeholder = t[element.dataset.placeholder]; });
  document.querySelectorAll("[data-calendar]").forEach((element) => { element.textContent = calendarCopy[element.dataset.calendar]; });
  document.querySelector(".menu-toggle").setAttribute("aria-label", "Menyunu aç");
  document.querySelector(".modal-close").setAttribute("aria-label", t.close);
  renderServices();
  renderBarbers();
  renderCalendar();
  syncThemeToggle();
  renderAbout();
}


function openBooking(serviceId = "", barberId = "") {
  const modal = document.querySelector("#booking-modal");
  document.querySelector("#booking-form-wrap").hidden = false;
  document.querySelector("#booking-success").hidden = true;
  document.querySelector("#booking-barber").value = barberId;
  updateBookingServices();
  document.querySelector("#booking-service").value = serviceId;
  calendarMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  selectedDate = "";
  selectedTime = "";
  availabilityKey = "";
  availabilityDays = {};
  document.querySelector("#selected-date").value = "";
  document.querySelector("#selected-time").value = "";
  document.querySelector("#calendar-error").hidden = true;
  renderCalendar();
  modal.hidden = false;
  document.body.classList.add("modal-open");
  document.querySelector("#booking-modal input").focus();
}

function closeBooking() {
  document.querySelector("#booking-modal").hidden = true;
  document.body.classList.remove("modal-open");
}

document.addEventListener("click", (event) => {


  const serviceButton = event.target.closest("[data-service-index]");
  if (serviceButton) openBooking(serviceButton.dataset.serviceIndex, serviceButton.dataset.bookerId);
  if (event.target.closest("#theme-toggle")) {
    setTheme(theme === "dark" ? "light" : "dark");
  }
  const dayButton = event.target.closest("[data-calendar-day]");
  if (dayButton && !dayButton.disabled) {
    selectedDate = dayButton.dataset.calendarDay;
    selectedTime = "";
    document.querySelector("#selected-date").value = selectedDate;
    document.querySelector("#selected-time").value = "";
    document.querySelector("#calendar-error").hidden = true;
    renderCalendar();
  }
  const timeButton = event.target.closest("[data-time]");
  if (timeButton) {
    selectedTime = timeButton.dataset.time;
    document.querySelector("#selected-time").value = selectedTime;
    document.querySelector("#calendar-error").hidden = true;
    renderTimeSlots();
  }
  if (event.target.closest("#calendar-prev")) {
    calendarMonth = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() - 1, 1);
    selectedDate = "";
    selectedTime = "";
    availabilityKey = "";
    document.querySelector("#selected-date").value = "";
    document.querySelector("#selected-time").value = "";
    renderCalendar();
  }
  if (event.target.closest("#calendar-next")) {
    calendarMonth = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 1);
    selectedDate = "";
    selectedTime = "";
    availabilityKey = "";
    document.querySelector("#selected-date").value = "";
    document.querySelector("#selected-time").value = "";
    renderCalendar();
  }
  const bookButton = event.target.closest("[data-open-booking]");
  if (bookButton) openBooking("", bookButton.dataset.bookerId ?? "");
  if (event.target.closest("[data-close-booking]") || event.target.id === "booking-modal") closeBooking();

  if (event.target.closest(".menu-toggle")) {
    const nav = document.querySelector(".nav-links");
    nav.classList.toggle("open");
    event.target.closest(".menu-toggle").textContent = nav.classList.contains("open") ? "×" : "☰";
  }
  if (event.target.closest(".nav-links a")) document.querySelector(".nav-links").classList.remove("open");
});

function resetCalendarSelection() {
  selectedDate = "";
  selectedTime = "";
  availabilityKey = "";
  availabilityDays = {};
  document.querySelector("#selected-date").value = "";
  document.querySelector("#selected-time").value = "";
  document.querySelector("#calendar-error").hidden = true;
  renderCalendar();
}

document.querySelector("#booking-barber").addEventListener("change", () => { updateBookingServices(); resetCalendarSelection(); });
document.querySelector("#booking-service").addEventListener("change", resetCalendarSelection);

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && !document.querySelector("#booking-modal").hidden) closeBooking();
});

document.querySelector("#booking-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!selectedBarberId() || !document.querySelector("#booking-service").value || !selectedDate || !selectedTime) {
    const error = document.querySelector("#calendar-error");
    error.textContent = calendarCopy.missing;
    error.hidden = false;
    error.scrollIntoView({ block: "nearest", behavior: "smooth" });
    return;
  }
  const form = event.currentTarget;
  const submit = form.querySelector("[type=submit]");
  const message = document.querySelector("#calendar-error");
  const fields = new FormData(form);
  submit.disabled = true;
  submit.querySelector("span").textContent = bookingMessages.sending;
  message.hidden = true;
  try {
    const response = await fetch("/api/appointments", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        customerName: fields.get("name"), email: fields.get("email"),
        barberId: fields.get("barberId"), serviceId: fields.get("serviceId"),
        date: selectedDate, time: selectedTime, note: fields.get("note")
      })
    });
    if (!response.ok) {
      const errorText = response.status === 409 ? bookingMessages.unavailable : bookingMessages.failed;
      if (response.status === 409) resetCalendarSelection();
      message.textContent = errorText;
      message.hidden = false;
      return;
    }
    document.querySelector("#booking-form-wrap").hidden = true;
    document.querySelector("#booking-success").hidden = false;
    document.querySelector("#booking-success-message").textContent = bookingMessages.confirmed;
  } catch {
    message.textContent = bookingMessages.failed;
    message.hidden = false;
  } finally {
    submit.disabled = false;
    submit.querySelector("span").textContent = copy.request;
  }
});

setTheme(theme);
applyContent();
loadCatalog();
